// Clean Supabase service without any verification references
import { authService, supabase } from './authentication';

// Re-export auth service
export { authService };
export { supabase };

// Clean services without verification
export const categoriesService = {
  async getCategories() {
    try {
      const { data, error } = await supabase
        .from('categories')
        .select('*')
        .eq('active', true)
        .order('sort_order');

      if (error) throw error;
      return data || [];
    } catch (error) {
      console.log('Categories not available');
      return [];
    }
  }
};

export const tasksService = {
  async getTasks(filters = {}) {
    try {
      let query = supabase
        .from('tasks')
        .select('*')
        .eq('status', 'active');

      const { data, error } = await query
        .order('created_at', { ascending: false })
        .limit(filters.limit || 20);

      if (error) throw error;
      return data || [];
    } catch (error) {
      console.log('Tasks not available');
      return [];
    }
  },

  async getTaskById(taskId) {
    console.log('Get task by ID not implemented yet');
    return null;
  },

  async createTask(taskData) {
    console.log('Create task not implemented yet');
    return { id: Date.now(), ...taskData };
  },

  async updateTask(taskId, updates) {
    console.log('Update task not implemented yet');
    return { id: taskId, ...updates };
  },

  async deleteTask(taskId) {
    console.log('Delete task not implemented yet');
    return true;
  },

  async getUserTasks(userId) {
    console.log('Get user tasks not implemented yet');
    return [];
  }
};

export const usersService = {
  async getProfile(userId) {
    return await authService.getProfile(userId);
  },

  async updateProfile(userId, updates) {
    return await authService.updateProfile(userId, updates);
  },

  async getWalletBalance(userId) {
    console.log('Wallet balance not implemented yet');
    return 0;
  }
};

// Placeholder services
export const fileService = {
  async uploadFile(file, bucket = 'task-files', folder = '') {
    console.log('File upload not implemented yet');
    // Return mock data to prevent errors
    return {
      data: {
        path: `${folder}/${file.name}`,
        publicUrl: `https://placeholder.com/${file.name}`
      }
    };
  }
};

// Removed subscription service - no longer needed for pricing

export const transactionsService = {
  async getUserTransactions() { return []; }
};

export const paymentService = {
  async processPayment() { return { success: false }; }
};

export const submissionsService = {
  async getUserSubmissions() { return []; }
};

export const notificationService = {
  async getUserNotifications(userId) { 
    console.log('Notifications not implemented yet');
    return []; 
  },
  async markAsRead(notificationId) {
    console.log('Mark as read not implemented yet');
    return true;
  }
};

export const realtimeService = {
  subscribeToNotifications(userId, callback) {
    console.log('Real-time notifications not implemented yet');
    return {
      unsubscribe: () => console.log('Unsubscribed from notifications')
    };
  },
  subscribeToTasks(callback) {
    console.log('Real-time tasks not implemented yet');
    return {
      unsubscribe: () => console.log('Unsubscribed from tasks')
    };
  }
};
export const analyticsService = {
  async trackEvent(eventName, properties = {}) {
    console.log('Analytics:', eventName, properties);
  },
  async trackPageView(pageName, properties = {}) {
    console.log('Page View:', pageName, properties);
  },
  async trackTaskInteraction(action, taskId, properties = {}) {
    console.log('Task Interaction:', action, taskId, properties);
  }
};

export default supabase;
